1	package hotel.reservations;
2	
3	import java.math.BigDecimal;
4	import java.sql.Connection;
5	import java.sql.Date;
6	import java.sql.PreparedStatement;
7	import java.sql.ResultSet;
8	import java.sql.SQLException;
9	import java.time.LocalDate;
10	import java.util.ArrayList;
11	import java.util.List;
12	import java.util.Optional;
13	import javax.sql.DataSource;
14	
15	/** Keeps the reservations in the database. */
16	public final class ReservationStore {
17	
18	    private static final String COLUMNS = "id, room_number, guest_name, guest_email, guest_cpf, check_in, check_out, "
19	            + "guests, rate_plan, nights, subtotal, discount, total, status, amount_paid, refund";
20	    /** PostgreSQL's code for a broken exclusion constraint: here, the room was already booked on one of the nights. */
21	    private static final String EXCLUSION_VIOLATION = "23P01";
22	
23	    private final DataSource dataSource;
24	
25	    public ReservationStore(DataSource dataSource) {
26	        this.dataSource = dataSource;
27	    }
28	
29	    /** Saves a new reservation; the database numbers it. */
30	    Reservation add(NewReservation request, Price price) {
31	        String insert = "INSERT INTO reservations (room_number, guest_name, guest_email, guest_cpf, check_in, "
32	                + "check_out, guests, rate_plan, nights, subtotal, discount, total, status, amount_paid) "
33	                + "VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?) RETURNING id";
34	        try (Connection connection = dataSource.getConnection();
35	                PreparedStatement statement = connection.prepareStatement(insert)) {
36	            statement.setInt(1, request.roomNumber());
37	            statement.setString(2, request.guest().name());
38	            statement.setString(3, request.guest().email());
39	            statement.setString(4, request.guest().cpf());
40	            statement.setDate(5, Date.valueOf(request.checkIn()));
41	            statement.setDate(6, Date.valueOf(request.checkOut()));
42	            statement.setInt(7, request.guests());
43	            statement.setString(8, request.ratePlan().name());
44	            statement.setInt(9, price.nights());
45	            statement.setBigDecimal(10, price.subtotal());
46	            statement.setBigDecimal(11, price.discount());
47	            statement.setBigDecimal(12, price.total());
48	            statement.setString(13, ReservationStatus.PENDING.name());
49	            statement.setBigDecimal(14, PriceCalculator.cents(BigDecimal.ZERO));
50	            try (ResultSet generated = statement.executeQuery()) {
51	                generated.next();
52	                return new Reservation(generated.getLong("id"), request, price);
53	            }
54	        } catch (SQLException failure) {
55	            if (EXCLUSION_VIOLATION.equals(failure.getSQLState())) {
56	                throw new HotelException(ErrorCode.ROOM_UNAVAILABLE,
57	                        "room " + request.roomNumber() + " is taken on some of those nights");
58	            }
59	            throw new IllegalStateException("could not save the reservation", failure);
60	        }
61	    }
62	
63	    /** Saves what changes in a reservation's life: the status, what was paid and what went back. */
64	    void update(Reservation reservation) {
65	        try (Connection connection = dataSource.getConnection();
66	                PreparedStatement statement = connection.prepareStatement(
67	                        "UPDATE reservations SET status = ?, amount_paid = ?, refund = ? WHERE id = ?")) {
68	            statement.setString(1, reservation.status().name());
69	            statement.setBigDecimal(2, reservation.amountPaid());
70	            statement.setBigDecimal(3, reservation.refund());
71	            statement.setLong(4, reservation.id());
72	            statement.executeUpdate();
73	        } catch (SQLException failure) {
74	            throw new IllegalStateException("could not save reservation " + reservation.id(), failure);
75	        }
76	    }
77	
78	    /** Whether a reservation that was not cancelled holds the room on any of the nights. */
79	    boolean isRoomTaken(int roomNumber, LocalDate checkIn, LocalDate checkOut) {
80	        try (Connection connection = dataSource.getConnection();
81	                PreparedStatement select = connection.prepareStatement(
82	                        "SELECT 1 FROM reservations WHERE room_number = ? AND status <> 'CANCELLED' "
83	                                + "AND check_in < ? AND ? < check_out")) {
84	            select.setInt(1, roomNumber);
85	            select.setDate(2, Date.valueOf(checkOut));
86	            select.setDate(3, Date.valueOf(checkIn));
87	            try (ResultSet rows = select.executeQuery()) {
88	                return rows.next();
89	            }
90	        } catch (SQLException failure) {
91	            throw new IllegalStateException("could not check room " + roomNumber, failure);
92	        }
93	    }
94	
95	    public Optional<Reservation> find(long id) {
96	        try (Connection connection = dataSource.getConnection();
97	                PreparedStatement select = connection.prepareStatement(
98	                        "SELECT " + COLUMNS + " FROM reservations WHERE id = ?")) {
99	            select.setLong(1, id);
100	            try (ResultSet rows = select.executeQuery()) {
101	                return rows.next() ? Optional.of(read(rows)) : Optional.empty();
102	            }
103	        } catch (SQLException failure) {
104	            throw new IllegalStateException("could not read reservation " + id, failure);
105	        }
106	    }
107	
108	    public List<Reservation> all() {
109	        try (Connection connection = dataSource.getConnection();
110	                PreparedStatement select = connection.prepareStatement(
111	                        "SELECT " + COLUMNS + " FROM reservations ORDER BY id");
112	                ResultSet rows = select.executeQuery()) {
113	            List<Reservation> reservations = new ArrayList<>();
114	            while (rows.next()) {
115	                reservations.add(read(rows));
116	            }
117	            return reservations;
118	        } catch (SQLException failure) {
119	            throw new IllegalStateException("could not read the reservations", failure);
120	        }
121	    }
122	
123	    private static Reservation read(ResultSet row) throws SQLException {
124	        Guest guest = new Guest(row.getString("guest_name"), row.getString("guest_email"), row.getString("guest_cpf"));
125	        NewReservation request = new NewReservation(
126	                row.getInt("room_number"),
127	                guest,
128	                row.getDate("check_in").toLocalDate(),
129	                row.getDate("check_out").toLocalDate(),
130	                row.getInt("guests"),
131	                RatePlan.valueOf(row.getString("rate_plan")));
132	        Price price = new Price(
133	                row.getInt("nights"), row.getBigDecimal("subtotal"), row.getBigDecimal("discount"),
134	                row.getBigDecimal("total"));
135	        return new Reservation(
136	                row.getLong("id"),
137	                request,
138	                price,
139	                ReservationStatus.valueOf(row.getString("status")),
140	                row.getBigDecimal("amount_paid"),
141	                row.getBigDecimal("refund"));
142	    }
143	}
