        case WEEKEND_PACKAGE:
            if (!isWeekendStay(request.checkIn(), request.checkOut())) {
                throw new HotelException(ErrorCode.INVALID_REQUEST, "weekend package must be Friday to Sunday");
            }
            break;
        case LONG_STAY:
            long nights = java.time.temporal.ChronoUnit.DAYS.between(request.checkIn(), request.checkOut());
            if (nights < 7) {
                throw new HotelException(ErrorCode.INVALID_REQUEST, "long stay requires at least 7 nights");
            }
            break;
        default:
            break;
    }
}

private boolean isValidCompanyCode(String code) {
    return code != null && (code.equals("TECNOSUL") || code.equals("AGROVALE") || code.equals("FARMAVIDA"));
}

private boolean isWeekendStay(java.time.LocalDate checkIn, java.time.LocalDate checkOut) {
    long nights = java.time.temporal.ChronoUnit.DAYS.between(checkIn, checkOut);
    if (nights != 2) {
        return false;
    }
    return checkIn.getDayOfWeek() == java.time.DayOfWeek.FRIDAY
            && checkOut.getDayOfWeek() == java.time.DayOfWeek.SUNDAY;
}

